window.AUTH=window.AUTH||{};window.AUTH["21-401"]={"d":"21-401","id":"2021/21-401","n":"ZF Automotive US, Inc. v. Luxshare, Ltd.","briefs":[{"k":"reply","label":"Reply of petitioners ZF Automotive US, Inc., et al.","date":"2021-11-01","url":"https://www.supremecourt.gov/DocketPDF/21/21-401/198385/20211101134621568_2021-11-01%20No.%2021-401%20ZF%20Cert%20Reply.pdf","side":"pet","n":6},{"k":"petitioner","label":"Brief of petitioners ZF Automotive US, Inc., et al.","date":"2022-01-24","url":"https://www.supremecourt.gov/DocketPDF/21/21-401/211145/20220124133821062_2022-01-24%20ZF%20Merits%20Opening%20Br%20w%20addendum.pdf","side":"pet","n":81},{"k":"petitioner","label":"Brief of petitioners AlixPartners, LLP and Mr. Simon Freakley","date":"2022-01-24","url":"https://www.supremecourt.gov/DocketPDF/21/21-401/211178/20220124150524579_21-401%2021-518%20BRIEF%20FOR%20PETITIONERS.pdf","side":"pet","n":43},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2022-01-31","url":"https://www.supremecourt.gov/DocketPDF/21/21-401/211877/20220131180354032_21-401tsacUnitedStates.pdf","side":"us","n":30},{"k":"respondent","label":"Brief of respondent Luxshare, Ltd.","date":"2022-02-23","url":"https://www.supremecourt.gov/DocketPDF/21/21-401/214808/20220223162457030_21-401%20ZF%20Automotive%20US%20Inc%20v%20Luxshare%20Ltd%20Brief%20for%20the%20Respondent.pdf","side":"res","n":113},{"k":"respondent","label":"Brief of respondent The Fund for Protection of Investors' Rights in Foreign States","date":"2022-02-23","url":"https://www.supremecourt.gov/DocketPDF/21/21-401/214798/20220223153440320_21-518_Fund_RespBrief.pdf","side":"res","n":39},{"k":"reply","label":"Reply of petitioners AlixPartners, LLP and Mr. Simon Freakley","date":"2022-03-11","url":"https://www.supremecourt.gov/DocketPDF/21/21-401/218326/20220311115036591_21-518%20Reply%20Brief.pdf","side":"pet","n":14},{"k":"reply","label":"Reply of petitioners ZF Automotive US, Inc., et al.","date":"2022-03-11","url":"https://www.supremecourt.gov/DocketPDF/21/21-401/218334/20220311121049656_2022-03-11%20No.%2021-401%20ZF%20Merits%20Reply%20Brief.pdf","side":"pet","n":26}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/596us2r42_3f14.pdf","tr":true,"items":[{"t":"case","label":"In re Application to Obtain Discovery for Use in Foreign Proceedings (Abdul Latif Jameel Transportation Co. v. FedEx Corp.)","cite":"939 F.3d 710","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/939/710/","op":2,"by":{"0":"5","1":"5, 12","2":"19","4":"passim","7":"23"}},{"t":"case","label":"In re Application of the Fund for Protection of Investor Rights in Foreign States v. AlixPartners, LLP","cite":"5 F.4th 216","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/5/216/","op":2,"by":{"0":"11"}},{"t":"case","label":"Hollingsworth v. Perry","cite":"558 U.S. 183","y":2010,"id":"scdb/2009-018","sc":1,"sum":"Yes. The applicants showed a fair prospect that the Court would grant certiorari and reverse or grant mandamus, because the District Court likely violated 28 U.S.C. § 2071 in amending its local rule, and showed likely irreparable harm with the equities favoring them. The Court stayed the streaming to other courthouses and did not address broadcasting generally.","sumSrc":"AI-generated brief","by":{"0":"1"}},{"t":"case","label":"Intel Corp. v. Advanced Micro Devices, Inc.","cite":"542 U.S. 241","y":2004,"id":"2003/02-572","sc":1,"op":5,"ar":15,"sum":"Holding that discovery is available for use in proceedings “within reasonable contemplation”.","sumSrc":"opinion","by":{"0":"7","1":"9, 38, 44, 45","2":"passim","3":"passim","4":"passim","5":"passim","6":"passim","7":"7, 19"}},{"t":"case","label":"Porter v. Dicken","cite":"328 U.S. 252","y":1946,"id":"scdb/1945-034","sc":1,"sum":"Under § 205 of the Emergency Price Control Act, authorizing the Price Administrator to bring injunction proceedings to enforce the-Act in either state or federal courts, a federal district court has jurisdiction to grant an injunction sought by the Price Administrator to restrain eviction of a tenant under an order of a state court where the Administrator alleges that eviction would violate the Act and regulations …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6"}},{"t":"case","label":"Porter v. Lee","cite":"328 U.S. 246","y":1946,"id":"scdb/1945-033","sc":1,"sum":"While an eviction suit by a landlord against a tenant was pending in a state court, the Price Administrator sued in a Federal District Court under § 205 of the Emergency Price Control Act to enjoin the landlord from evicting that tenant \"or any other tenant\" and from violating the Rent Regulation for Housing (promulgated under the Emergency Price Control Act), which forbids the eviction of tenants so long as they …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6"}},{"t":"case","label":"Application of Consorcio Ecuatoriano de Telecomunicaciones S.A. v. JAS Forwarding (USA), Inc.","cite":"747 F.3d 1262","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/747/1262/","by":{"1":"44"}},{"t":"case","label":"Aspden v. Nixon","cite":"45 U.S. 467","y":1846,"id":"scdb/1846-038","sc":1,"sum":"Where a person domiciled in England died, leaving property both in England and Pennsylvania, and the executor took out letters testamentary in both countries, in a suit in England against the executor by the administrator. of a deceased claimant, the parties were restricted. tovthe limits of^fhe country to which their letters extended. _.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"24","2":"21"}},{"t":"case","label":"AT&T Mobility LLC v. Concepcion","cite":"563 U.S. 333","y":2011,"id":"2010/09-893","sc":1,"sum":"The Court held the Federal Arbitration Act preempts state laws that \"stand as obstacles to the FAA's objectives.\"","sumSrc":"Oyez","by":{"1":"37, 50","2":"28","7":"23"}},{"t":"case","label":"Banco Nacional de Cuba v. Sabbatino","cite":"376 U.S. 398","y":1964,"id":"1963/16","sc":1,"sum":"The Supreme Court held that it will not decide the validity of a decree by a foreign government absent a treaty or other agreement. It did not matter that the taking violated customary international law. The majority noted that a judicial decision on this issue without a treaty would strain U.S.-Cuba relations.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Canada Malting Co. v. Patterson Steamships","cite":"285 U.S. 413","y":1932,"id":"scdb/1931-048","sc":1,"ar":6,"sum":"1. In a suit in admiralty between foreigners it is ordinarily within the discretion of the District Court to refuse to retain jurisdiction; and the exercise of its discretion will not be disturbed unless abused.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24","2":"21"}},{"t":"case","label":"Dolan v. United States Postal Service","cite":"546 U.S. 481","y":2006,"id":"2005/04-848","sc":1,"sum":"The Court ruled that the \"negligent transmission\" exception was inapplicable to Dolan's case, and therefore sovereign immunity had been waived and her case could proceed. The Court accepted Dolan's argument that the exception was only meant to encompass cases of late, missing, or incorrectly delivered mail.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Epic Systems Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"1":"37, 50","2":"27","4":"40"}},{"t":"case","label":"FCC v. AT&T Inc.","cite":"562 U.S. 397","y":2011,"id":"2010/09-1279","sc":1,"op":1,"sum":"The Court held that corporations do not have a right of personal privacy that would prevent the disclosure of public records handed over to federal agencies.","sumSrc":"Oyez","by":{"1":"20","2":"19","3":"16, 17, 33","5":"19","7":"1, 3"}},{"t":"case","label":"Food Delivery Holding 12 S.a.r.l. v. DeWitty & Associates CHTD","cite":"538 F. Supp. 3d 21","y":2021,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/538/21/","sum":"Noting same dynamic in litigation.","sumSrc":"brief:1","by":{"1":"47"}},{"t":"case","label":"Food Marketing Institute v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"sum":"Where commercial or financial information is both customarily and actually treated as private by its owner and provided to the government under an assurance of privacy, the information is “confidential” within the meaning of 5 U. S. C. §552(b)(4), the Freedom of Information Act’s Exemption 4.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"18","2":"17","3":"15","4":"passim","5":"18, 32"}},{"t":"case","label":"Gulf Oil Corp. v. Gilbert","cite":"330 U.S. 501","y":1947,"id":"scdb/1946-068","sc":1,"sum":"It did not abuse its discretion in doing so.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Guo v. Deutsche Bank Securities Inc. (In re Guo)","cite":"965 F.3d 96","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/965/96/","sum":"Noting that Professor Smit’s 1965 article “can thus be read . . . as referring solely to state-sponsored arbitral bodies”.","sumSrc":"brief:7","by":{"1":"43, 51, 52","7":"17, 18"}},{"t":"case","label":"Hanson v. Denckla","cite":"357 U.S. 235","y":1958,"id":"1957/107","sc":1,"sum":"While domiciled in Pennsylvania, a woman executed in Delaware a revocable deed of trust making a Delaware trust company trustee of certain securities, reserving the income for life and providing that the remainder should be paid to such parties as she should appoint by inter vivos or testamentary instrument. Later, after becoming domiciled in Florida, where she remained until her death, she executed (1) an inter …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24","2":"21"}},{"t":"case","label":"Hartford Fire Insurance Co. v. California","cite":"509 U.S. 764","y":1993,"id":"1992/91-1111","sc":1,"sum":"The Court, speaking through Justice Antonin Scalia, held that a boycott exists when, in order to coerce a target into certain terms on one transaction, parties refuse to engage in other, unrelated transactions with the target. On most counts, the plaintiffs' allegations, construed favorably, described boycotts.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"Hay Group, Inc. v. E.B.S. Acquisition Corp.","cite":"360 F.3d 404","y":2004,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/360/404/","by":{"1":"39"}},{"t":"case","label":"Hilton v. Guyot","cite":"159 U.S. 113","y":1895,"id":"scdb/1894-250","sc":1,"sum":"A citizen and resident of this country, who has his principal place of business here, but has an agent in a foreign country, and is accustomed to purchase and store large quantities of goods there, and, in a suit brought against him by a citizen and in a court of that country, appears and defends with the sole object of preventing his property within the jurisdiction, but not in the custody of that court, from being …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"24","5":"27"}},{"t":"case","label":"Home Depot U.S.A., Inc. v. Jackson","cite":"139 S. Ct. 1743","y":2019,"id":"2018/17-1471","sc":1,"sum":"Neither the general removal provision, 28 U. S. C. §1441(a), nor the removal provision in the Class Action Fairness Act of 2005, §1453(b), permit a third-party counterclaim defendant to remove a class-action claim from state to federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"27"}},{"t":"case","label":"Joint Anti-Fascist Refugee Committee v. McGrath","cite":"341 U.S. 123","y":1951,"id":"scdb/1950-068","sc":1,"sum":"The judgments are reversed and the cases are remanded to the District Court with instructions to deny the motions that the complaints be dismissed for failure to state claims upon which relief could be granted. Pp. 124-125, 142. 85 U. S. App. D. C. 255, 177 F. 2d 79; 86 U. S. App. D. C. 287, 182 F. 2d 368, reversed. Opinion of BURTON, J. For the opinions of the Justices constituting the majority of the Court, see: …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Louisiana v. Mississippi","cite":"202 U.S. 1","y":1906,"id":"scdb/1905-097","sc":1,"sum":"The act of Congress admitting Louisiana having given that State all islands within three leagues of her coast, and the subsequent act of Congress admitting Mississippi having purported to give that State all islands within six leagues of her shore, and some islands within nine miles of the Louisiana coast heing also within eighteen miles of the Mississippi shore, although the apparent inconsistency is reconcilable, …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"24","2":"21, 22"}},{"t":"case","label":"Mitsubishi Motors Corp. v. Soler ChryslerPlymouth, Inc.","cite":"473 U.S. 614","y":1985,"id":"1984/83-1569","sc":1,"ar":1,"sum":"The Supreme Court held that claims arising under the Sherman Act and encompassed in a valid arbitration clause in an international commercial transaction are arbitrable under the federal Arbitration Act. Justice John Paul Stevens dissented, arguing that a fair construction of the arbitration clause does not encompass antitrust claims.","sumSrc":"Oyez","by":{"1":"50","4":"14, 18, 30, 44","7":"8"}},{"t":"case","label":"Moran v. Sturges","cite":"154 U.S. 256","y":1894,"id":"scdb/1893-283","sc":1,"sum":"On the 31st day of July,. 1891, proceedings were commenced in the Supreme Court of the State of New York for the voluntary dissolution of á Steam Tow Boat Company; a corporation organized under the laws of that State, and an order was made on that day restraining creditors from bringing action and requiring all to show cause, on the 16th day of November, 1891, before a referee, why the prayer of the petitioner …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Moses H. Cone Memorial Hospital v. Mercury Construction Corp.","cite":"460 U.S. 1","y":1983,"id":"1982/81-1203","sc":1,"sum":"Petitioner, a hospital located in North Carolina, entered into a contract with respondent contractor, an Alabama corporation, for construction of additions to the hospital building. Contract disputes were to be initially referred to the architect who was hired to design and oversee the construction project. Disputes decided by the architect or not decided within a specified time could be submitted to binding …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"39"}},{"t":"case","label":"National Broadcasting Co. v. Bear Stearns & Co.","cite":"165 F.3d 184","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/165/184/","op":2,"by":{"1":"26, 40, 44, 51","2":"4, 9, 28","3":"21, 25, 27","4":"36, 37, 38","5":"5, 7, 8, 17","7":"19"}},{"t":"case","label":"North American Commercial Co. v. United States","cite":"171 U.S. 110","y":1898,"id":"scdb/1897-164","sc":1,"sum":"By the agreement of March 12, 1890, between the United States and the North American Commercial Company, that company contracted to pay to the United States a rental of $60,000 per year, during the term of the contract, for the privilege of killing an agreed number of seals each year, subject to a proportionate reduction of this fixed rental, in case of a limitation in the number; and also a further sum of seven …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"24","2":"21","5":"29"}},{"t":"case","label":"Page(s) Pereira v. Sessions","cite":"138 S. Ct. 2105","y":2018,"id":"2017/17-459","sc":1,"op":13,"sum":"The Court held that a notice to appear for a removal hearing that does not specify the place and time of the hearing does not trigger the stop-time rule of 8 U.S.C. § 1229b(b)(1), which gives the attorney general discretion to cancel removal for an alien who, among other criteria, has been continuously physically present in the country for at least ten years.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Peter v. Nantkwest, Inc.","cite":"140 S. Ct. 365","y":2019,"id":"2019/18-801","sc":1,"op":1,"sum":"The Court held that the phrase “[a]ll the expenses of the proceedings” in 35 U.S.C. § 145 does not include attorneys’ fees incurred as a result of defending the agency in § 145 litigation.","sumSrc":"Oyez","by":{"1":"22","2":"21"}},{"t":"case","label":"Republic of Kazakhstan v. Biedermann International","cite":"168 F.3d 880","y":1999,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/168/880/","op":1,"by":{"1":"40, 44","3":"25","4":"36","6":"13–14"}},{"t":"case","label":"Servotronics, Inc. v. Rolls-Royce PLC","cite":"975 F.3d 689","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/975/689/","op":2,"by":{"1":"passim","2":"24","3":"16, 18, 19, 25, 26","4":"28, 30, 36, 42","7":"18, 19"}},{"t":"case","label":"Stolt-Nielsen S.A. v. AnimalFeeds International Corp.","cite":"559 U.S. 662","y":2010,"id":"2009/08-1198","sc":1,"op":2,"sum":"The Court held that imposing class arbitration on parties who have not agreed to authorize class arbitration is inconsistent with the Federal Arbitration Act.","sumSrc":"Oyez","by":{"1":"28","7":"11"}},{"t":"case","label":"Underhill v. Hernandez","cite":"168 U.S. 250","y":1897,"id":"scdb/1897-017","sc":1,"sum":"Hernandez was in command of a revolutionary army in Venezuela when an engagement took place with the government forces which resulted in the defeat of the latter, and the occupation of Bolivar by the former. Underhill was living in Bolivar, where he had constructed a waterworks system for the' city under a contract with the government, and carried on a machinery repair business. He applied for a passport to leave …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Whitman v. American Trucking Associations","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"const","label":"Article I, Section 8, Clause 9","text":"To constitute Tribunals inferior to the supreme Court;","by":{"1":"22","2":"21","5":"30"}},{"t":"usc","label":"5 U.S.C. § 552b","url":"https://www.law.cornell.edu/uscode/text/5/552b","subs":["(c)(10)"],"stext":{"head":"§552b. Open meetings","paras":[[0,"(a) For purposes of this section—"],[1,"(1) the term \"agency\" means any agency, as defined in section 552(e) 1 of this title, headed by a collegial body composed of two or more individual members, a majority of whom are appointed to such position by the President with the advice and consent of the Senate, and any subdivision thereof authorized to act on behalf of the agency;"],[1,"(2) the term \"meeting\" means the deliberations of at least the number of individual agency members required to take action on behalf of the agency where such deliberations determine or result in the joint conduct or disposition of official agency business, but does not include deliberations required or permitted by subsection (d) or (e); and"],[1,"(3) the term \"member\" means an individual who belongs to a collegial body heading an agency."],[0,"(b) Members shall not jointly conduct or dispose of agency business other than in accordance with this section. Except as provided in subsection (c), every portion of every meeting of an agency shall be open to public observation."],[0,"(c) Except in a case where the agency finds that the public interest requires otherwise, the second sentence of subsection (b) shall not apply to any portion of an agency meeting, and the requirements of subsections (d) and (e) shall not apply to any information pertaining to such meeting otherwise required by this section to be disclosed to the public, where the agency properly determines that such portion or portions of its meeting or the disclosure of such information is likely to—"],[1,"(1) disclose matters that are (A) specifically authorized under criteria established by an Executive order to be kept secret in the interests of national defense or foreign policy and (B) in fact properly classified pursuant to such Executive order;"],[1,"(2) relate solely to the internal personnel rules and practices of an agency;"],[1,"(3) disclose matters specifically exempted from disclosure by statute (other than section 552 of this title), provided that such statute (A) requires that the matters be withheld from the public in such a manner as to leave no discretion on the issue, or (B) establishes particular criteria for withholding or refers to particular types of matters to be withheld;"],[1,"(4) disclose trade secrets and commercial or financial information obtained from a person and privileged or confidential;"],[1,"(5) involve accusing any person of a crime, or formally censuring any person;"],[1,"(6) disclose information of a personal nature where disclosure would constitute a clearly unwarranted invasion of personal privacy;"],[1,"(7) disclose investigatory records compiled for law enforcement purposes, or information which if written would be contained in such records, but only to the extent that the production of such records or information would (A) interfere with enforcement proceedings, (B) deprive a person of a right to a fair trial or an impartial adjudication, (C) constitute an unwarranted invasion of personal privacy, (D) disclose the identity of a confidential source and, in the case of a record compiled by a criminal law enforcement authority in the course of a criminal investigation, or by an agency conducting a lawful national security intelligence investigation, confidential information furnished only by the confidential source, (E) disclose investigative techniques and procedures, or (F) endanger the life or physical safety of law enforcement personnel;"],[1,"(8) disclose information contained in or related to examination, operating, or condition reports prepared by, on behalf of, or for the use of an agency responsible for the regulation or supervision of financial institutions;"],[1,"(9) disclose information the premature disclosure of which would—"],[2,"(A) in the case of an agency which regulates currencies, securities, commodities, or financial institutions, be likely to (i) lead to significant financial speculation in currencies, securities, or commodities, or (ii) significantly endanger the stability of any financial institution; or"],[2,"(B) in the case of any agency, be likely to significantly frustrate implementation of a proposed agency action,"],[1,"except that subparagraph (B) shall not apply in any instance where the agency has already disclosed to the public the content or nature of its proposed action, or where the agency is required by law to make such disclosure on its own initiative prior to taking final agency action on such proposal; or"],[1,"(10) specifically concern the agency's issuance of a subpena, or the agency's participation in a civil action or proceeding, an action in a foreign court or international tribunal, or an arbitration, or the initiation, conduct, or disposition by the agency of a particular case of formal agency adjudication pursuant to the procedures in section 554 of this title or otherwise involving a determination on the record after opportunity for a hearing."],[0,"(d)(1) Action under subsection (c) shall be taken only when a majority of the entire membership of the agency (as defined in subsection (a)(1)) votes to take such action. A separate vote of the agency members shall be taken with respect to each agency meeting a portion or portions of which are proposed to be closed to the public pursuant to subsection (c), or with respect to any information which is proposed to be withheld under subsection (c). A single vote may be taken with respect to a series of meetings, a portion or portions of which are proposed to be closed to the public, or with respect to any information concerning such series of meetings, so long as each meeting in such series involves the same particular matters and is scheduled to be held no more than thirty days after the initial meeting in such series. The vote of each agency member participating in such vote shall be recorded and no proxies shall be allowed."],[0,"(2) Whenever any person whose interests may be directly affected by a portion of a meeting requests that the agency close such portion to the public for any of the reasons referred to in paragraph (5), (6), or (7) of subsection (c), the agency, upon request of any one of its members, shall vote by recorded vote whether to close such meeting."],[0,"(3) Within one day of any vote taken pursuant to paragraph (1) or (2), the agency shall make publicly available a written copy of such vote reflecting the vote of each member on the question. If a portion of a meeting is to be closed to the public, the agency shall, within one day of the vote taken pursuant to paragraph (1) or (2) of this subsection, make publicly available a full written explanation of its action closing the portion together with a list of all persons expected to attend the meeting and their affiliation."],[0,"(4) Any agency, a majority of whose meetings may properly be closed to the public pursuant to paragraph (4), (8), (9)(A), or (10) of subsection (c), or any combination thereof, may provide by regulation for the closing of such meetings or portions thereof in the event that a majority of the members of the agency votes by recorded vote at the beginning of such meeting, or portion thereof, to close the exempt portion or portions of the meeting, and a copy of such vote, reflecting the vote of each member on the question, is made available to the public. The provisions of paragraphs (1), (2), and (3) of this subsection and subsection (e) shall not apply to any portion of a meeting to which such regulations apply: Provided, That the agency shall, except to the extent that such information is exempt from disclosure under the provisions of subsection (c), provide the public with public announcement of the time, place, and subject matter of the meeting and of each portion thereof at the earliest practicable time."],[0,"(e)(1) In the case of each meeting, the agency shall make public announcement, at least one week before the meeting, of the time, place, and subject matter of the meeting, whether it is to be open or closed to the public, and the name and phone number of the official designated by the agency to respond to requests for information about the meeting. Such announcement shall be made unless a majority of the members of the agency determines by a recorded vote that agency business requires that such meeting be called at an earlier date, in which case the agency shall make public announcement of the time, place, and subject matter of such meeting, and whether open or closed to the public, at the earliest practicable time."],[0,"(2) The time or place of a meeting may be changed following the public announcement required by paragraph (1) only if the agency publicly announces such change at the earliest practicable time. The subject matter of a meeting, or the determination of the agency to open or close a meeting, or portion of a meeting, to the public, may be changed following the public announcement required by this subsection only if (A) a majority of the entire membership of the agency determines by a recorded vote that agency business so requires and that no earlier announcement of the change was possible, and (B) the agency publicly announces such change and the vote of each member upon such change at the earliest practicable time."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/552b?type=usc&year=mostrecent&link-type=html"},"head":"§552b. Open meetings","tname":"Government Organization and Employees","by":{"1":"26","2":"26","4":"25","5":"29, 30","7":"9"}},{"t":"usc","label":"9 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/9/2","stext":{"head":"§2. Validity, irrevocability, and enforcement of agreements to arbitrate","paras":[[0,"A written provision in any maritime transaction or a contract evidencing a transaction involving commerce to settle by arbitration a controversy thereafter arising out of such contract or transaction, or the refusal to perform the whole or any part thereof, or an agreement in writing to submit to arbitration an existing controversy arising out of such a contract, transaction, or refusal, shall be valid, irrevocable, and enforceable, save upon such grounds as exist at law or in equity for the revocation of any contract or as otherwise provided in chapter 4."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/2?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":2,"head":"§2. Validity, irrevocability, and enforcement of agreements to arbitrate","tname":"Arbitration","by":{"1":"37","2":"27","4":"23"}},{"t":"usc","label":"9 U.S.C. § 4","url":"https://www.law.cornell.edu/uscode/text/9/4","by":{"1":"38","4":"23"}},{"t":"usc","label":"9 U.S.C. § 5","url":"https://www.law.cornell.edu/uscode/text/9/5","stext":{"head":"§5. Appointment of arbitrators or umpire","paras":[[0,"If in the agreement provision be made for a method of naming or appointing an arbitrator or arbitrators or an umpire, such method shall be followed; but if no method be provided therein, or if a method be provided and any party thereto shall fail to avail himself of such method, or if for any other reason there shall be a lapse in the naming of an arbitrator or arbitrators or umpire, or in filling a vacancy, then upon the application of either party to the controversy the court shall designate and appoint an arbitrator or arbitrators or umpire, as the case may require, who shall act under the said agreement with the same force and effect as if he or they had been specifically named therein; and unless otherwise provided in the agreement the arbitration shall be by a single arbitrator."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/5?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§5. Appointment of arbitrators or umpire","tname":"Arbitration","by":{"1":"38","4":"23"}},{"t":"usc","label":"9 U.S.C. § 7","url":"https://www.law.cornell.edu/uscode/text/9/7","stext":{"head":"§7. Witnesses before arbitrators; fees; compelling attendance","paras":[[0,"The arbitrators selected either as prescribed in this title or otherwise, or a majority of them, may summon in writing any person to attend before them or any of them as a witness and in a proper case to bring with him or them any book, record, document, or paper which may be deemed material as evidence in the case. The fees for such attendance shall be the same as the fees of witnesses before masters of the United States courts. Said summons shall issue in the name of the arbitrator or arbitrators, or a majority of them, and shall be signed by the arbitrators, or a majority of them, and shall be directed to the said person and shall be served in the same manner as subpoenas to appear and testify before the court; if any person or persons so summoned to testify shall refuse or neglect to obey said summons, upon petition the United States district court for the district in which such arbitrators, or a majority of them, are sitting may compel the attendance of such person or persons before said arbitrator or arbitrators, or punish said person or persons for contempt in the same manner provided by law for securing the attendance of witnesses or their punishment for neglect or refusal to attend in the courts of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/7?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":2,"head":"§7. Witnesses before arbitrators; fees; compelling attendance","tname":"Arbitration","by":{"1":"23, 38, 39","2":"28","3":"7","4":"10, 42, 43","7":"19"}},{"t":"usc","label":"9 U.S.C. § 8","url":"https://www.law.cornell.edu/uscode/text/9/8","by":{"1":"30"}},{"t":"usc","label":"9 U.S.C. § 9","url":"https://www.law.cornell.edu/uscode/text/9/9","by":{"1":"30, 38","4":"20"}},{"t":"usc","label":"9 U.S.C. § 10","url":"https://www.law.cornell.edu/uscode/text/9/10","subs":["(a)"],"stext":{"head":"§10. Same; vacation; grounds; rehearing","paras":[[0,"(a) In any of the following cases the United States court in and for the district wherein the award was made may make an order vacating the award upon the application of any party to the arbitration—"],[1,"(1) where the award was procured by corruption, fraud, or undue means;"],[1,"(2) where there was evident partiality or corruption in the arbitrators, or either of them;"],[1,"(3) where the arbitrators were guilty of misconduct in refusing to postpone the hearing, upon sufficient cause shown, or in refusing to hear evidence pertinent and material to the controversy; or of any other misbehavior by which the rights of any party have been prejudiced; or"],[1,"(4) where the arbitrators exceeded their powers, or so imperfectly executed them that a mutual, final, and definite award upon the subject matter submitted was not made."],[0,"(b) If an award is vacated and the time within which the agreement required the award to be made has not expired, the court may, in its discretion, direct a rehearing by the arbitrators."],[0,"(c) The United States district court for the district wherein an award was made that was issued pursuant to section 580 of title 5 may make an order vacating the award upon the application of a person, other than a party to the arbitration, who is adversely affected or aggrieved by the award, if the use of arbitration or the award is clearly inconsistent with the factors set forth in section 572 of title 5."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/10?type=usc&year=mostrecent&link-type=html"},"head":"§10. Same; vacation; grounds; rehearing","tname":"Arbitration","by":{"1":"31","4":"20","7":"8"}},{"t":"usc","label":"9 U.S.C. § 11","url":"https://www.law.cornell.edu/uscode/text/9/11","by":{"1":"31"}},{"t":"usc","label":"9 U.S.C. § 12","url":"https://www.law.cornell.edu/uscode/text/9/12","by":{"1":"31"}},{"t":"usc","label":"9 U.S.C. § 13","url":"https://www.law.cornell.edu/uscode/text/9/13","by":{"1":"30"}},{"t":"usc","label":"9 U.S.C. § 15","url":"https://www.law.cornell.edu/uscode/text/9/15","by":{"1":"30"}},{"t":"usc","label":"9 U.S.C. § 16","url":"https://www.law.cornell.edu/uscode/text/9/16","by":{"1":"31"}},{"t":"usc","label":"9 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/9/201","by":{"1":"41, 43","5":"27, 31"}},{"t":"usc","label":"9 U.S.C. § 202","url":"https://www.law.cornell.edu/uscode/text/9/202","by":{"1":"23"}},{"t":"usc","label":"9 U.S.C. § 203","url":"https://www.law.cornell.edu/uscode/text/9/203","by":{"1":"31"}},{"t":"usc","label":"9 U.S.C. § 205","url":"https://www.law.cornell.edu/uscode/text/9/205","by":{"1":"31"}},{"t":"usc","label":"9 U.S.C. § 207","url":"https://www.law.cornell.edu/uscode/text/9/207","by":{"1":"23, 31","4":"20, 21"}},{"t":"usc","label":"9 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/9/301","by":{"1":"43","5":"27, 31"}},{"t":"usc","label":"16 U.S.C. § 971c","url":"https://www.law.cornell.edu/uscode/text/16/971c","subs":["(b)"],"by":{"1":"23","4":"25"}},{"t":"usc","label":"16 U.S.C. § 973n","url":"https://www.law.cornell.edu/uscode/text/16/973n","stext":{"head":"§973n. Arbitration","paras":[[0,"In the event of a dispute requiring the establishment of an arbitral tribunal under Article 6 of the Treaty, the Secretary of State, in consultation with the Secretary, shall appoint the arbitrator to be appointed by the United States under paragraph 3 of that Article, and shall represent the United States in reaching agreement under such paragraph with each Pacific Island Party involved concerning the appointment of the presiding arbitrator of the tribunal."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/973n?type=usc&year=mostrecent&link-type=html"},"head":"§973n. Arbitration","tname":"Conservation","by":{"1":"23","2":"26","4":"25","6":"10"}},{"t":"usc","label":"18 U.S.C. § 3190","url":"https://www.law.cornell.edu/uscode/text/18/3190","by":{"1":"23","4":"25"}},{"t":"usc","label":"19 U.S.C. § 4452","url":"https://www.law.cornell.edu/uscode/text/19/4452","subs":["(f)(3)"],"by":{"1":"23","4":"25"}},{"t":"usc","label":"22 U.S.C. § 270-270g","url":"https://www.law.cornell.edu/uscode/text/22/270-270g","subs":["(1958)"],"by":{"1":"7","3":"31","5":"5, 6"}},{"t":"usc","label":"22 U.S.C. § 270d","url":"https://www.law.cornell.edu/uscode/text/22/270d","subs":["(1958)"],"by":{"1":"33","4":"2, 3, 33"}},{"t":"usc","label":"22 U.S.C. § 290k-11","url":"https://www.law.cornell.edu/uscode/text/22/290k-11","stext":{"head":"§290k–11. Arbitral awards; enforcement; full faith and credit; Federal Arbitration Act inapplicable; exclusiveness of district court jurisdiction","paras":[[0,"(a) An award of an arbitral tribunal resolving a dispute arising under Article 57 or Article 58 of the Convention shall create a right arising under a treaty of the United States. The pecuniary obligations imposed by such an award shall be enforced and shall be given the same full faith and credit as if the award were a final judgment of a court of general jurisdiction of one of the several States. The Federal Arbitration Act (9 U.S.C. 1, et seq.) shall not apply to enforcement of awards rendered pursuant to the Convention."],[0,"(b) The district courts of the United States (including the courts enumerated in section 460 of title 28) shall have exclusive jurisdiction over actions and proceedings under subsection (a) of this section, regardless of the amount in controversy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/290k-11?type=usc&year=mostrecent&link-type=html"},"head":"§290k–11. Arbitral awards; enforcement; full faith and credit; Federal Arbitration Act inapplicable; exclusiveness of district court jurisdiction","tname":"Foreign Relations and Intercourse","by":{"1":"23","2":"26","4":"25"}},{"t":"usc","label":"22 U.S.C. § 1650a","url":"https://www.law.cornell.edu/uscode/text/22/1650a","subs":["(a)"],"stext":{"head":"§1650a. Arbitration awards under the Convention","paras":[[0,"(a) Treaty rights; enforcement; full faith and credit; nonapplication of Federal Arbitration Act"],[0,"An award of an arbitral tribunal rendered pursuant to chapter IV of the convention shall create a right arising under a treaty of the United States. The pecuniary obligations imposed by such an award shall be enforced and shall be given the same full faith and credit as if the award were a final judgment of a court of general jurisdiction of one of the several States. The Federal Arbitration Act (9 U.S.C. 1 et seq.) shall not apply to enforcement of awards rendered pursuant to the convention."],[0,"(b) Jurisdiction; amount in controversy"],[0,"The district courts of the United States (including the courts enumerated in section 460 of title 28) shall have exclusive jurisdiction over actions and proceedings under subsection (a) of this section, regardless of the amount in controversy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/1650a?type=usc&year=mostrecent&link-type=html"},"head":"§1650a. Arbitration awards under the Convention","tname":"Foreign Relations and Intercourse","by":{"1":"23","2":"26","3":"31","4":"25","5":"10, 27, 29, 29"}},{"t":"usc","label":"22 U.S.C. § 2710","url":"https://www.law.cornell.edu/uscode/text/22/2710","subs":["(d)(1)"],"by":{"1":"26"}},{"t":"usc","label":"22 U.S.C. § 6912","url":"https://www.law.cornell.edu/uscode/text/22/6912","subs":["(a)(5)(D)","(a)(11)"],"by":{"1":"23, 23","4":"25"}},{"t":"usc","label":"22 U.S.C. § 7427","url":"https://www.law.cornell.edu/uscode/text/22/7427","subs":["(c)(3)"],"by":{"1":"23","4":"25"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"1":"1"}},{"t":"usc","label":"28 U.S.C. § 1696","url":"https://www.law.cornell.edu/uscode/text/28/1696","subs":["(a)"],"stext":{"head":"§1696. Service in foreign and international litigation","paras":[[0,"(a) The district court of the district in which a person resides or is found may order service upon him of any document issued in connection with a proceeding in a foreign or international tribunal. The order may be made pursuant to a letter rogatory issued, or request made, by a foreign or international tribunal or upon application of any interested person and shall direct the manner of service. Service pursuant to this subsection does not, of itself, require the recognition or enforcement in the United States of a judgment, decree, or order rendered by a foreign or international tribunal."],[0,"(b) This section does not preclude service of such a document without an order of court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1696?type=usc&year=mostrecent&link-type=html"},"head":"§1696. Service in foreign and international litigation","tname":"Judiciary and Judicial Procedure","by":{"1":"30, 15, 30","3":"18, 18","4":"8, 29, 30, 31","5":"25, 25, 26, 27, 28"}},{"t":"usc","label":"28 U.S.C. § 1781","url":"https://www.law.cornell.edu/uscode/text/28/1781","subs":["(a)(1)","(a)(2)"],"stext":{"head":"§1781. Transmittal of letter rogatory or request","paras":[[0,"(a) The Department of State has power, directly, or through suitable channels—"],[1,"(1) to receive a letter rogatory issued, or request made, by a foreign or international tribunal, to transmit it to the tribunal, officer, or agency in the United States to whom it is addressed, and to receive and return it after execution; and"],[1,"(2) to receive a letter rogatory issued, or request made, by a tribunal in the United States, to transmit it to the foreign or international tribunal, officer, or agency to whom it is addressed, and to receive and return it after execution."],[0,"(b) This section does not preclude—"],[1,"(1) the transmittal of a letter rogatory or request directly from a foreign or international tribunal to the tribunal, officer, or agency in the United States to whom it is addressed and its return in the same manner; or"],[1,"(2) the transmittal of a letter rogatory or request directly from a tribunal in the United States to the foreign or international tribunal, officer, or agency to whom it is addressed and its return in the same manner."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1781?type=usc&year=mostrecent&link-type=html"},"head":"§1781. Transmittal of letter rogatory or request","tname":"Judiciary and Judicial Procedure","by":{"1":"28, 29, 29","4":"8, 30","5":"27, 28"}},{"t":"usc","label":"28 U.S.C. § 1782","url":"https://www.law.cornell.edu/uscode/text/28/1782","subs":["(1958)","(a)","(1964)","(a)(1964)"],"stext":{"head":"§1782. Assistance to foreign and international tribunals and to litigants before such tribunals","paras":[[0,"(a) The district court of the district in which a person resides or is found may order him to give his testimony or statement or to produce a document or other thing for use in a proceeding in a foreign or international tribunal, including criminal investigations conducted before formal accusation. The order may be made pursuant to a letter rogatory issued, or request made, by a foreign or international tribunal or upon the application of any interested person and may direct that the testimony or statement be given, or the document or other thing be produced, before a person appointed by the court. By virtue of his appointment, the person appointed has power to administer any necessary oath and take the testimony or statement. The order may prescribe the practice and procedure, which may be in whole or part the practice and procedure of the foreign country or the international tribunal, for taking the testimony or statement or producing the document or other thing. To the extent that the order does not prescribe otherwise, the testimony or statement shall be taken, and the document or other thing produced, in accordance with the Federal Rules of Civil Procedure."],[0,"A person may not be compelled to give his testimony or statement or to produce a document or other thing in violation of any legally applicable privilege."],[0,"(b) This chapter does not preclude a person within the United States from voluntarily giving his testimony or statement, or producing a document or other thing, for use in a proceeding in a foreign or international tribunal before any person and in any manner acceptable to him."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1782?type=usc&year=mostrecent&link-type=html"},"op":36,"ar":6,"head":"§1782. Assistance to foreign and international tribunals and to litigants before such tribunals","tname":"Judiciary and Judicial Procedure","by":{"1":"1, 7, 6, 17, 27, 28","2":"passim, passim","3":"4, 6, passim, 4, passim, 3","4":"passim, passim","5":"passim, passim, passim","6":"passim","7":"1"}},{"t":"usc","label":"28 U.S.C. § 4101","url":"https://www.law.cornell.edu/uscode/text/28/4101","subs":["(3)"],"by":{"1":"23","4":"25"}},{"t":"law","label":"Pub. L. No. 85-906","url":"https://www.govinfo.gov/link/statute/72/1743","by":{"1":"7, 34, 35","2":"3, 4, 21, 24","3":"6, 22","4":"32, 36","5":"5","7":"7, 15"}},{"t":"law","label":"Pub. L. No. 87-187","url":"https://www.govinfo.gov/link/statute/75/415","by":{"1":"22","2":"21","5":"30"}},{"t":"law","label":"Pub. L. No. 88-619","url":"https://www.govinfo.gov/link/statute/78/995","by":{"1":"8, 21, 22, 36","2":"4","4":"3, 27, 28","5":"6"}},{"t":"law","label":"Pub. L. No. 91-368","url":"https://www.govinfo.gov/link/statute/84/692","by":{"1":"43"}},{"t":"law","label":"Pub. L. No. 101-369","url":"https://www.govinfo.gov/link/statute/104/448","by":{"1":"43"}},{"t":"rule","label":"Fed. R. Civ. P. 45","url":"https://www.law.cornell.edu/rules/frcp/rule_45","subs":["(c)(1)"],"by":{"1":"39","4":"43"}},{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"sum":"The Court held that a firearm purchaser's intent to sell their gun to another buyer is necessary information for the seller's records.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"BG Group, PLC v. Republic of Argentina","cite":"572 U.S. 25","y":2014,"id":"2013/12-138","sc":1,"op":1,"sum":"The Court held that it is the duty of the arbitrating party in a contract lawsuit to interpret provisions outlined in the contract.","sumSrc":"Oyez","by":{"2":"36","4":"47","5":"passim","6":"10, 11, 12"}},{"t":"case","label":"Bloate v. United States","cite":"559 U.S. 196","y":2010,"id":"2009/08-728","sc":1,"op":1,"sum":"The Court held that the time granted to prepare pretrial motions is not automatically granted exclusion from the Speedy Trial Act's 70-day time limit.","sumSrc":"Oyez","by":{"2":"19","3":"16"}},{"t":"case","label":"Boys Markets, Inc. v. Retail Clerks Union, Local 770","cite":"398 U.S. 235","y":1970,"id":"1969/768","sc":1,"sum":"In the circumstances of this case-where the grievance was subject to arbitration under the collectivebargaining agreement, petitioner was ready for arbitration when the strike was enjoined, and the District Court concluded that respondent's violations of the no-strike clause were causing petitioner irreparable injury--the Norris-LaGuardia Act does not bar the granting of injunctive relief. Sinclair Refining Co. v. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19","3":"16"}},{"t":"case","label":"Burlington N. & Santa Fe Ry. Co. v. White","cite":"548 U.S. 53","y":2006,"id":"2005/05-259","sc":1,"sum":"In a decision authored by Justice Stephen Breyer and joined by Chief Justice Roberts and six other justices, the Court held that in order to prevail on a claim of retaliatory discrimination, \"a plaintiff must show that a reasonable employee would have found the challenged action materially adverse, which in this context means it well might have dissuaded a reasonable worker from making or supporting a charge of discrimination.\" (internal citations omitted) Justice Samuel Alito wrote separately, agreeing with the result but arguing that the test adopted by the other members of the Court would eventually prove problematic.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Granite Rock Co. v. Int’l Bhd. Of Teamsters","cite":"561 U.S. 287","y":2010,"id":"2009/08-1214","sc":1,"op":1,"sum":"The Court held that federal courts have jurisdiction to determine whether or not a collective bargaining agreement was formed between two parties when the agreement is disputed, but neither party makes a challenge to the arbitration clause contained in the agreement.","sumSrc":"Oyez","by":{"2":"37"}},{"t":"case","label":"Lozano v. Montoya Alvarez","cite":"572 U.S. 1","y":2014,"id":"2013/12-820","sc":1,"sum":"The Court held that the policy of equitable tolling does not apply to the statute of limitations outlined in the Hauge Convention's provision on international child abduction.","sumSrc":"Oyez","by":{"2":"36, 37"}},{"t":"case","label":"Servotronics, Inc. v. Boeing Co.","cite":"954 F.3d 209","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/954/209/","op":2,"by":{"2":"19","4":"passim","7":"10, 11"}},{"t":"case","label":"United Sav. Ass’n v. Timbers of Inwood Forest Assocs., Ltd.","cite":"484 U.S. 365","y":1988,"id":"1987/86-1602","sc":1,"sum":"Undersecured creditors are not entitled to compensation under § 362(d)(1) for the delay caused by the automatic stay in foreclosing on their collateral.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19","3":"16, 19"}},{"t":"case","label":"United Steelworkers of Am. v. Warrior & Golf Nav. Co.","cite":"363 U.S. 574","y":1960,"id":"1959/443","sc":1,"sum":"It erred in doing so, and the judgment is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37","4":"14","7":"9"}},{"t":"case","label":"Whitney v. Robertson","cite":"124 U.S. 190","y":1888,"id":"scdb/1887-097","sc":1,"sum":"The treaty of February 8, 1867, with the Dominican Republic (art. 9) provides that “ no higher or other duty shall be imposed on the importation into the United States of any article the growth, produce, or manufacture of the Dominican Republic, or of her fisheries, than are or shall be payable on the like articles the growth, produce, or manufacture of any other foreign country or of its fisheries.” The convention …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"36"}},{"t":"usc","label":"9 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/9/1","stext":{"head":"§1. \"Maritime transactions\" and \"commerce\" defined; exceptions to operation of title","paras":[[0,"\"Maritime transactions\", as herein defined, means charter parties, bills of lading of water carriers, agreements relating to wharfage, supplies furnished vessels or repairs to vessels, collisions, or any other matters in foreign commerce which, if the subject of controversy, would be embraced within admiralty jurisdiction; \"commerce\", as herein defined, means commerce among the several States or with foreign nations, or in any Territory of the United States or in the District of Columbia, or between any such Territory and another, or between any such Territory and any State or foreign nation, or between the District of Columbia and any State or Territory or foreign nation, but nothing herein contained shall apply to contracts of employment of seamen, railroad employees, or any other class of workers engaged in foreign or interstate commerce."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/1?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1. \"Maritime transactions\" and \"commerce\" defined; exceptions to operation of title","tname":"Arbitration","by":{"2":"27","3":"25","4":"34"}},{"t":"usc","label":"9 U.S.C. § 307","url":"https://www.law.cornell.edu/uscode/text/9/307","stext":{"head":"§307. Application","paras":[[0,"Chapter 1 applies to actions and proceedings brought under this chapter to the extent chapter 1 is not in conflict with this chapter or the Inter-American Convention as ratified by the United States. This chapter applies to the extent that this chapter is not in conflict with chapter 4."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/307?type=usc&year=mostrecent&link-type=html"},"head":"§307. Application","tname":"Arbitration","by":{"2":"27","3":"31","4":"43","7":"19"}},{"t":"law","label":"Pub. L. No. 89-532","url":"https://www.govinfo.gov/link/statute/80/344","by":{"2":"26"}},{"t":"law","label":"Pub. L. No. 100-202","by":{"2":"26"}},{"t":"law","label":"Pub. L. No. 100-330","url":"https://www.govinfo.gov/link/statute/102/600","by":{"2":"26"}},{"t":"law","label":"Pub. L. No. 104-106","url":"https://www.govinfo.gov/link/plaw/104/public/106","by":{"2":"4"}},{"t":"case","label":"Al Fayed v. CIA","cite":"229 F.3d 272","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/229/272/","sum":"Concluding that the United States is not a “person” under Section 1782.","sumSrc":"brief:3","by":{"3":"31, 33"}},{"t":"case","label":"COMSAT Corp. v. National Sci. Found.","cite":"190 F.3d 269","y":1999,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/190/269/","by":{"3":"25"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith Inc. v. Dabit","cite":"547 U.S. 71","y":2006,"id":"2005/04-1371","sc":1,"sum":"The Court held that \"holder\" class actions such as Dabit's are \"in connection with the purchase or sale\" of a security and therefore are pre-empted by SLUSA.","sumSrc":"Oyez","by":{"3":"19"}},{"t":"usc","label":"9 U.S.C. § 208","url":"https://www.law.cornell.edu/uscode/text/9/208","stext":{"head":"§208. Application","paras":[[0,"Chapter 1 applies to actions and proceedings brought under this chapter to the extent that chapter is not in conflict with this chapter or the Convention as ratified by the United States. This chapter applies to the extent that this chapter is not in conflict with chapter 4."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/208?type=usc&year=mostrecent&link-type=html"},"head":"§208. Application","tname":"Arbitration","by":{"3":"31","4":"43","7":"19"}},{"t":"usc","label":"22 U.S.C. § 270-270c","url":"https://www.law.cornell.edu/uscode/text/22/270-270c","subs":["(1958)"],"by":{"3":"31"}},{"t":"usc","label":"22 U.S.C. § 270d-270g","url":"https://www.law.cornell.edu/uscode/text/22/270d-270g","subs":["(1958)"],"by":{"3":"31"}},{"t":"usc","label":"28 U.S.C. § 1602","url":"https://www.law.cornell.edu/uscode/text/28/1602","by":{"3":"31"}},{"t":"reg","label":"22 C.F.R. § 92.54","url":"https://www.ecfr.gov/current/title-22/section-92.54","by":{"3":"3"}},{"t":"case","label":"Am. Airlines, Inc. v. Louisville & Jefferson Cnty. Air Bd.","cite":"269 F.2d 811","y":1959,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/269/811/","by":{"4":"15"}},{"t":"case","label":"Artuz v. Bennett","cite":"531 U.S. 4","y":2000,"id":"2000/99-1238","sc":1,"sum":"The Court held that an application for state postconviction relief containing procedurally barred claims is properly filed within the meaning of the Antiterrorism and Effective Death Penalty Act of 1996.","sumSrc":"Oyez","by":{"4":"44"}},{"t":"case","label":"Bartlett v. L. Bartlett & Son Co.","cite":"93 N.W. 473","y":1903,"court":"Wis.","url":"https://www.courtlistener.com/c/N.W./93/473/","by":{"4":"15"}},{"t":"case","label":"Bernhardt v. Polygraphic Co. of Am.","cite":"350 U.S. 198","y":1956,"id":"1955/49","sc":1,"sum":"The judgment of the Court of Appeals is reversed and the cause is remanded to the District Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"14","7":"9"}},{"t":"case","label":"Bostock v. Clayton Cnty.","cite":"140 S. Ct. 1731","y":2020,"id":"2019/17-1618","sc":1,"ar":2,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"4":"17","5":"9, 19, 21"}},{"t":"case","label":"Brush v. Fisher","cite":"38 N.W. 446","y":1888,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./38/446/","by":{"4":"15"}},{"t":"case","label":"Bumpass v. Webb","cite":"4 Port. 65","y":1836,"court":"Ala.","url":"https://www.courtlistener.com/c/Port./4/65/","by":{"4":"15"}},{"t":"case","label":"Burchell v. Marsh","cite":"58 U.S. 344","y":1854,"id":"scdb/1854-030","sc":1,"sum":"If an award is within the submission, and contains the honest decision of the arbitra--' tors, after a full and fair bearing of the parties, a court of equity will notset it aside for error, either in law or fact.","sumSrc":"Headnote (U.S. Reports)","by":{"4":"21"}},{"t":"case","label":"Cahn v. Int’l Ladies’ Garment Union","cite":"311 F.2d 113","y":1962,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/311/113/","by":{"4":"21"}},{"t":"case","label":"Cal. Prune & Apricot Growers’ Ass’n v. Catz Am. Co.","cite":"60 F.2d 788","y":1932,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/60/788/","by":{"4":"15"}},{"t":"case","label":"vii Campbell v. Campbell","cite":"44 App. D.C. 142","y":1915,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/App.%20D.C./44/142/","by":{"4":"15"}},{"t":"case","label":"Carey v. Westinghouse Elec. Corp.","cite":"375 U.S. 261","y":1964,"id":"1963/21","sc":1,"sum":"Whether the dispute be considered one involving work assignment or one concerning representation, it is not within the exclusive jurisdiction of the National Labor Relations Board, and there is no barrier to use of the arbitration procedure. Pp. 263-273. 11 N. Y. 2d 452, 184 N. E. 2d 298, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"14"}},{"t":"case","label":"CEEG (Shanghai) Solar Sci. & Tech. Co., Ltd v. LUMOS LLC","cite":"829 F.3d 1201","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/829/1201/","by":{"4":"21"}},{"t":"case","label":"Commonwealth Coatings Corp. v. Cont’l Cas. Co.","cite":"393 U.S. 145","y":1968,"id":"1968/14","sc":1,"sum":"Arbitrators should disclose to the parties any dealings which might create an impression of possible bias, and since the business connection between the arbitrator and the prime contractor was not disclosed here, the award can be vacated under § 10 of the United States Arbitration Act, which authorizes vacation of an award \"procured by... undue means\" or \"where there was evident partiality... in the arbitrators.\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"14, 20"}},{"t":"case","label":"Dorsey v. United States","cite":"567 U.S. 260","y":2012,"id":"2011/11-5683","sc":1,"sum":"The Court held that criminals who had committed drug crimes before the passage of the Fair Sentencing Act of 2010 but were sentenced after its passage were entitled to the sentencing provisions laid out in the Act.","sumSrc":"Oyez","by":{"4":"36"}},{"t":"case","label":"Dworkin v. Caledonian Ins. Co.","cite":"226 S.W. 846","y":1920,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W./226/846/","by":{"4":"15"}},{"t":"case","label":"E. Eng’g Co. v. Ocean City","cite":"167 A. 522","y":1933,"court":"N.J.","url":"https://www.courtlistener.com/c/A./167/522/","by":{"4":"15"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"138 S. Ct. 1134","y":2018,"id":"2017/16-1362","sc":1,"sum":"The Court decided that because service advisors at car dealerships are “salesm[e]n . . . primarily engaged in . . . servicing automobiles,” 29 U.S.C. § 213(b)(10)(A), they are exempt from the Fair Labor Standards Act's overtime-pay requirements.","sumSrc":"Oyez","by":{"4":"17, 37"}},{"t":"case","label":"Eyre-Shoemaker, Inc, v. Buffalo, R & P R Co","cite":"193 F. 387","y":1912,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F./193/387/","by":{"4":"15"}},{"t":"case","label":"Gilmer v. Interstate/Johnson Lane Corp.","cite":"500 U.S. 20","y":1991,"id":"1990/90-18","sc":1,"sum":"An ADEA claim can be subjected to compulsory arbitration.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"40"}},{"t":"case","label":"Hartford Fire Ins. Co. v. Hon","cite":"92 N.W. 746","y":1902,"court":"Neb.","url":"https://www.courtlistener.com/c/N.W./92/746/","by":{"4":"15"}},{"t":"case","label":"viii Hennen v. St. Paul Mercury Ins. Co.","cite":"250 N.W.2d 840","y":1977,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W.2d/250/840/","by":{"4":"15"}},{"t":"case","label":"Henry v. Lehigh Valley Coal Co.","cite":"64 A. 635","y":1906,"court":"Pa.","url":"https://www.courtlistener.com/c/A./64/635/","op":1,"by":{"4":"15"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"4":"27"}},{"t":"case","label":"Hickman v. Taylor","cite":"329 U.S. 495","y":1947,"id":"scdb/1946-035","sc":1,"sum":"Under the Federal Rules of Civil Procedure, plaintiff in a suit in a federal district court against certain tug owners to recover for the death of a seaman in the sinking of the tug filed numerous interrogatories directed to the defendants, including one inquiring whether any statements of members of the crew were taken in connection with the accident and requesting that exact copies of all such written statements …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"43"}},{"t":"case","label":"Jones v. Enoree Power Co.","cite":"75 S.E. 452","y":1912,"court":"S.C.","url":"https://www.courtlistener.com/c/S.E./75/452/","by":{"4":"15"}},{"t":"case","label":"Kanmak Mills, Inc. v. Soc’y Brand Hat Co.","cite":"236 F.2d 240","y":1956,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/236/240/","by":{"4":"15"}},{"t":"case","label":"Karaha Bodas Co. v. Perusahaan Pertambangan Minyak Dan Gas Bumi Negara","cite":"364 F.3d 274","y":2004,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/364/274/","by":{"4":"13"}},{"t":"case","label":"Kiobel v. Cravath, Swaine & Moore","cite":"895 F.3d 238","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/895/238/","by":{"4":"46"}},{"t":"case","label":"Lamps Plus, Inc. v. Varela","cite":"139 S. Ct. 1407","y":2019,"id":"2018/17-988","sc":1,"sum":"Under the Federal Arbitration Act, an ambiguous agreement cannot provide the necessary contractual basis for concluding that the parties agreed to submit to class arbitration.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"40"}},{"t":"case","label":"Landegger v. Bayerische Hypotheken Und Wechsel Bank","cite":"357 F. Supp. 692","y":1972,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./357/692/","by":{"4":"34"}},{"t":"case","label":"Lanza v. Fin. Indus. Regul. Auth.","cite":"953 F.3d 159","y":2020,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/953/159/","by":{"4":"21"}},{"t":"case","label":"Managed Care Advisory Grp., LLC v. CIGNA Healthcare, Inc.","cite":"939 F.3d 1145","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/939/1145/","by":{"4":"43"}},{"t":"case","label":"Morgan v. United States","cite":"298 U.S. 468","y":1936,"id":"scdb/1935-127","sc":1,"sum":"1. Under § 310 of the Packers & Stockyards Act, a hearing is prerequisite to a valid order of the Secretary of Agriculture fixing rates for Market Agencies.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"21"}},{"t":"case","label":"Mut. Ben. Health & Acc. Ass’n v. United Cas. Co.","cite":"142 F.2d 390","y":1944,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/142/390/","by":{"4":"15"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"141 S. Ct. 1474","y":2021,"id":"2020/19-863","sc":1,"sum":"A notice to appear sufficient to trigger the Illegal Immigration Reform and Immigrant Responsibility Act of 1996’s stop-time rule is a single document containing all the information about an individual’s removal hearing specified in 8 U. S. C. §1229(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"4":"38, 44"}},{"t":"case","label":"NLRB v. Radio & Television Broad. Eng’rs Union","cite":"364 U.S. 573","y":1961,"id":"1960/69","sc":1,"sum":"The Board's order is not entitled to enforcement, because the Board had not. discharged its duty under § 10 (k) to \"determine the dispute.\" It should have made -an affirmative award of the work between the employees of the competing unions. Pp. 574-586. 272 F. 2d 713, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"14","7":"9"}},{"t":"case","label":"Oncale v. Sundowner Offshore Servs., Inc.","cite":"523 U.S. 75","y":1998,"id":"1997/96-568","sc":1,"sum":"The Court held that while Title VII does not prohibit all verbal or physical harassment in the workplace, it does bar all forms of discrimination \"because of\" sex. Such discrimination, whether motivated by sexual desire or not, is actionable so long at it places its victim in an objectively disadvantageous working condition, regardless of the victim's gender.","sumSrc":"Oyez","by":{"4":"17"}},{"t":"case","label":"x Parsons v. Ambos","cite":"48 S.E. 696","y":1904,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E./48/696/","by":{"4":"15"}},{"t":"case","label":"Pa. Dep’t of Corr. v. Yeskey","cite":"524 U.S. 206","y":1998,"id":"1997/97-634","sc":1,"sum":"The Court held that under the ADA no \"public entity\" may discriminate against qualified disabled individuals due to their disability. Moreover, the Court stated that the ADA's protections extended to cover prison inmates as well as any other liberated citizen.","sumSrc":"Oyez","by":{"4":"37"}},{"t":"case","label":"Pension Ben. Guar. Corp. v. LTV Corp.","cite":"496 U.S. 633","y":1990,"id":"1989/89-390","sc":1,"sum":"The PBGC's restoration decision was not arbitrary and capricious or contrary to law under § 706(2)(A).","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"37"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"4":"31"}},{"t":"case","label":"Red Cross Line v. Atl. Fruit Co.","cite":"264 U.S. 109","y":1924,"id":"scdb/1923-067","sc":1,"sum":"1. A decision of the highest court of a State excluding maritime contracts from the operation of a state statute, not as a matter of statutory construction but due to its opinion that the Federal Constitution so requires, presents a constitutional question reviewable here.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"14"}},{"t":"case","label":"Sandifer v. U.S. Steel Corp.","cite":"571 U.S. 220","y":2014,"id":"2013/12-417","sc":1,"sum":"The Court held that putting on safety garments constitutes \"changing clothes\" under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"4":"18"}},{"t":"case","label":"SAS Inst., Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"4":"38"}},{"t":"case","label":"Scherk v. Alberto-Culver Co.","cite":"417 U.S. 506","y":1974,"id":"1973/73-781","sc":1,"ar":1,"sum":"The arbitration clause is to be respected and enforced by federal courts in accord with the explicit provisions of the United States Arbitration Act that an arbitration agreement, such as is here involved, \"shall be valid, irrevocable, and enforceable, save upon such grounds as exist at law or in equity for the revocation of any contract.\" 9 U. S. C. §§ 1, 2. Wilko v. Swan, supra, distinguished.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"14","7":"9"}},{"t":"case","label":"Scott v. Avery","cite":"5 H.L. Cas. 811","y":1856,"url":"https://www.courtlistener.com/c/H.L.%20Cas./5/811/","by":{"4":"16"}},{"t":"case","label":"Siegel v. Lewis","cite":"358 N.E.2d 484","y":1976,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/358/484/","by":{"4":"15"}},{"t":"case","label":"Tobey v. Cnty. of Bristol","cite":"23 F. Cas. 1313","y":1845,"court":"C.C.D. Mass.","url":"https://www.courtlistener.com/c/F.%20Cas./23/1313/","by":{"4":"14"}},{"t":"case","label":"xi Toyo Tire Holdings of Americas Inc. v. Cont’l Tire N. Am., Inc.","cite":"609 F.3d 975","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/609/975/","by":{"4":"23"}},{"t":"case","label":"United States v. Quality Stores, Inc.","cite":"572 U.S. 141","y":2014,"id":"2013/12-1408","sc":1,"sum":"The Court found that severance payments made to employees who were unwillingly laid off are taxable under the Federal Insurance Contributions Act.","sumSrc":"Oyez","by":{"4":"18, 26"}},{"t":"case","label":"Univ. of Notre Dame (USA) in England v. TJAC Waterloo, LLC","cite":"861 F.3d 287","y":2017,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/861/287/","by":{"4":"31"}},{"t":"case","label":"U.S. Wrestling Fed’n v. Wrestling Div. of AAU, Inc.","cite":"605 F.2d 313","y":1979,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/605/313/","by":{"4":"14"}},{"t":"case","label":"Wash. Nat’l Ins. Co. v. OBEX Grp. LLC","cite":"958 F.3d 126","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/958/126/","by":{"4":"43"}},{"t":"case","label":"Wis. Cent. Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"4":"17, 45"}},{"t":"case","label":"Wilko v. Swan","cite":"201 F.2d 439","y":1953,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/201/439/","by":{"4":"14"}},{"t":"case","label":"Yahoo! Inc. v. Microsoft Corp.","cite":"983 F. Supp. 2d 310","y":2013,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/983/310/","by":{"4":"23"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"4":"26"}},{"t":"case","label":"Yusuf Ahmed Alghanim & Sons v. Toys “R” Us, Inc.","cite":"126 F.3d 15","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/126/15/","by":{"4":"13"}},{"t":"usc","label":"9 U.S.C. § 3","url":"https://www.law.cornell.edu/uscode/text/9/3","by":{"4":"23"}},{"t":"usc","label":"9 U.S.C. § 304","url":"https://www.law.cornell.edu/uscode/text/9/304","by":{"4":"20"}},{"t":"usc","label":"18 U.S.C. § 1391","url":"https://www.law.cornell.edu/uscode/text/18/1391","by":{"4":"8"}},{"t":"usc","label":"18 U.S.C. § 2518","url":"https://www.law.cornell.edu/uscode/text/18/2518","by":{"4":"26"}},{"t":"usc","label":"18 U.S.C. § 3060","url":"https://www.law.cornell.edu/uscode/text/18/3060","by":{"4":"26"}},{"t":"usc","label":"18 U.S.C. § 3184","url":"https://www.law.cornell.edu/uscode/text/18/3184","by":{"4":"26"}},{"t":"usc","label":"22 U.S.C. § 270","url":"https://www.law.cornell.edu/uscode/text/22/270","subs":["(1958)"],"ar":1,"tname":"Foreign Relations and Intercourse","by":{"4":"2, 3, 33","6":"15"}},{"t":"usc","label":"22 U.S.C. § 270a","url":"https://www.law.cornell.edu/uscode/text/22/270a","subs":["(1958)"],"by":{"4":"2, 3, 33"}},{"t":"usc","label":"22 U.S.C. § 270c","url":"https://www.law.cornell.edu/uscode/text/22/270c","subs":["(1958)"],"by":{"4":"2, 3, 33"}},{"t":"usc","label":"22 U.S.C. § 270e","url":"https://www.law.cornell.edu/uscode/text/22/270e","subs":["(1958)"],"by":{"4":"2, 3, 33"}},{"t":"usc","label":"22 U.S.C. § 270g","url":"https://www.law.cornell.edu/uscode/text/22/270g","subs":["(1958)"],"by":{"4":"2, 3, 33"}},{"t":"usc","label":"28 U.S.C. § 517","url":"https://www.law.cornell.edu/uscode/text/28/517","by":{"4":"48"}},{"t":"usc","label":"28 U.S.C. § 1741","url":"https://www.law.cornell.edu/uscode/text/28/1741","by":{"4":"8, 27","7":"4"}},{"t":"usc","label":"28 U.S.C. § 2414","url":"https://www.law.cornell.edu/uscode/text/28/2414","by":{"4":"25"}},{"t":"usc","label":"28 U.S.C. § 4102","url":"https://www.law.cornell.edu/uscode/text/28/4102","by":{"4":"25"}},{"t":"case","label":"Estes v. Texas","cite":"381 U.S. 532","y":1965,"id":"1964/256","sc":1,"sum":"The televising over petitioner's objections of the courtroom proceedings of petitioner's criminal trial, in which there was widespread public interest, was inherently invalid as infringing the fundamental right to a fair trial guaranteed by the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"5":"29"}},{"t":"case","label":"Fed. Republic of Nig. v. VR Advisory Servs.","cite":"2022 WL 320211","y":2022,"court":"2d Cir. Feb. 3","by":{"5":"32"}},{"t":"case","label":"Filarsky v. Delia","cite":"566 U.S. 377","y":2012,"id":"2011/10-1018","sc":1,"sum":"The Court found that a private attorney retained by a governmental agency is not prevented from claiming qualified immunity simply because they are not a full-time employee of the agency.","sumSrc":"Oyez","by":{"5":"40"}},{"t":"case","label":"Frigaliment Importing Co. v. B.N.S. Int’l Sales Corp.","cite":"190 F. Supp. 116","y":1960,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./190/116/","by":{"5":"15"}},{"t":"case","label":"GE Energy Power Conversion Fr. SAS, Corp. v. Outokumpu Stainless USA, LLC","cite":"140 S. Ct. 1637","y":2020,"id":"2019/18-1048","sc":1,"sum":"The Court held that the Convention on the Recognition and Enforcement of Foreign Arbitral Awards does not prohibit the application of domestic equitable estoppel doctrine to allow a nonsignatory to an arbitration agreement to compel arbitration.","sumSrc":"Oyez","by":{"5":"31"}},{"t":"case","label":"Islamic Republic of Pak. v. Arnold & Porter Kaye Scholer LLP","cite":"2019 WL 1559433","y":2019,"court":"D.D.C. Apr. 10","sum":"Noting that courts “have regularly found that arbitrations conducted pursuant to Bilateral Investment Treaties, and specifically by the ICSID, qualify as international tribunals under the statute.”.","sumSrc":"brief:5","by":{"5":"46, 47"}},{"t":"case","label":"Kingdomware Techs., Inc. v. United States","cite":"579 U.S. 162","y":2016,"id":"2015/14-916","sc":1,"sum":"The Court determined that the Court had jurisdiction to address the merits of the case even if the contracts had already been performed, and the Department of Veterans Affairs’ “set-aside” for veteran-owned businesses is mandatory.","sumSrc":"Oyez","by":{"5":"25"}},{"t":"case","label":"OJSC Ukrnafta v. Carpatsky Petroleum Corp.","cite":"2009 WL 2877156","y":2009,"court":"D. Conn. Aug. 27","by":{"5":"47"}},{"t":"case","label":"Peralta v. Heights Med. Ctr., Inc.","cite":"485 U.S. 80","y":1988,"id":"1987/86-1430","sc":1,"sum":"The holding below contravenes this Court's precedents, under which a judgment entered without notice or service violates the Due Process Clause. See, e. g., Mullane v. Central Hanover Bank & Trust Co., 339 U. S. 306; Armstrong v. Manzo, 380 U. S. 545. The argument that appellant suffered no harm from the default judgment since the same judgment would again be entered on retrial absent a meritorious defense is …","sumSrc":"Syllabus (U.S. Reports)","by":{"5":"28"}},{"t":"case","label":"Republic of Ecuador v. Bjorkman","cite":"801 F. Supp. 2d 1121","y":2011,"court":"D. Colo.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/801/1121/","by":{"5":"47","6":"14–15"}},{"t":"case","label":"Republic of Ecuador v. Stratus Consulting, Inc.","cite":"2013 WL 2352425","y":2013,"court":"D. Colo. May 29","by":{"5":"47"}},{"t":"case","label":"Republic of Kaz. v. Lawler","cite":"2019 WL 5558997","y":2019,"court":"D. Ariz. Oct. 28","by":{"5":"47"}},{"t":"case","label":"Smith v. United States","cite":"508 U.S. 223","y":1993,"id":"1992/91-8674","sc":1,"sum":"Authored by Justice Sandra Day O'Connor, the Court ruled that a criminal who trades his or her firearm for drugs \"uses\" it \"during and in relation to . . . [a] drug trafficking crime,\" which is within the bounds of the sentence enhancement. Justice O'Connor wrote that Congress intended to make the word \"use\" as broad as possible when it wrote the law.","sumSrc":"Oyez","by":{"5":"18, 20, 21, 31","6":"4, 5, 6"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(c)(1)"],"by":{"5":"20"}},{"t":"case","label":"Azar v. Allina Health Servs.","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"6":"19"}},{"t":"case","label":"Bailey v. United States","cite":"516 U.S. 137","y":1995,"id":"1995/94-7448","sc":1,"sum":"The proximity and accessibility test for \"use\" is so broad that no independent role remains for \"carry.\" \"Use\" in Section 924(c)(1) requires more than proximity and accessibility that might embolden a defendant. It requires active employment of the firearm by the defendant, making the firearm an operative factor in relation to the predicate offense.","sumSrc":"Oyez","by":{"6":"5, 6, 8-9"}},{"t":"case","label":"Chevron Corp. v. Berlinger","cite":"629 F.3d 297","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/629/297/","by":{"6":"14"}},{"t":"case","label":"Islamic Republic of Pak. v. Arnold & Porter Kaye Scholer LLP","cite":"2019 U.S. Dist. LEXIS 61780","y":2019,"court":"D.D.C. Apr.10","by":{"6":"15"}},{"t":"case","label":"OJSC Ukrnafta v. Carpatsky Petroleum Corp., 3:09 MC 265","cite":"2009 U.S. Dist. LEXIS 109492","y":2009,"court":"D. Conn. Aug. 27","by":{"6":"15"}},{"t":"case","label":"Watson v. United States","cite":"552 U.S. 74","y":2007,"id":"2007/06-571","sc":1,"by":{"6":"5, 6"}},{"t":"case","label":"Murphy v. NCAA","cite":"138 S. Ct. 1461","y":2018,"id":"2017/16-476","sc":1,"sum":"The Court decided that provisions of the Professional and Amateur Sports Protection Act (PASPA) that prohibit state authorization and licensing of sports gambling schemes violate the Constitution’s anticommandeering rule, and that no other PASPA provisions are severable from the provisions at issue.","sumSrc":"Oyez","by":{"7":"22"}},{"t":"case","label":"Tapia v. United States","cite":"564 U.S. 319","y":2011,"id":"2010/10-5400","sc":1,"sum":"The Court held that a district court may not give a defendant a longer prison sentence based on speculation about if and when the defendant would be able to participate in an inmate drug rehabilitation program.","sumSrc":"Oyez","by":{"7":"14"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"7":"18"}},{"t":"usc","label":"18 U.S.C. § 3491","url":"https://www.law.cornell.edu/uscode/text/18/3491","by":{"7":"4"}}]};